        "@type": "Question",
        "name": "What is defense robotics data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of sensor data and operator demonstrations that train and test autonomous systems for military logistics, explosive ordnance disposal, maintenance inspection, and installation security, focused on degraded conditions such as GPS loss, night, and rough terrain."
        }
      },
      {
        "@type": "Question",
        "name": "Which defense applications does Gamasome support?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Non-weapons autonomy: logistics and resupply vehicles, EOD and hazardous-material robots, maintenance inspection, installation perimeter sensing, and evaluation data. We don't collect data for weapons targeting or engagement."
        }
      },
      {
        "@type": "Question",
        "name": "How do you handle controlled or sensitive data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Data category, access, storage location, and chain of custody are agreed during scoping and built into the capture plan. Where a program requires specific certifications or clearances, we confirm up front what we can support."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect data in GPS-denied conditions?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. We capture LiDAR, camera, thermal, and IMU data with reference positioning so autonomy can be trained and evaluated when satellite navigation is degraded or unavailable."
        }
      },
      {
        "@type": "Question",
        "name": "How do you capture EOD robot training data safely?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Teleoperated demonstrations use inert training items and follow range safety procedures, recording the robot's states, wrist cameras, and force data."
        }
      },
      {
        "@type": "Question",
        "name": "How does this relate to your national security work?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Defense covers military autonomy programs. Our national security page covers critical infrastructure and homeland programs such as substation, port, and facility protection."
        }
      }
